package corpus

import (
	"bytes"
	"os"
	"testing"
)

// The bench_mixed variant data (issue #191) is the corpus half of the
// data-driven bench: 64 wire buffers that every language's serialize-blind
// driver benches, regenerated by `make bench-variants`
// (bench/tools/variantgen). This test is the committed data's gate — it
// needs no serialize runtime and no generated codec, so it runs in the root
// module wherever `go test ./...` runs.
//
// What it pins, and why each clause exists:
//
//   - variant 0 IS the golden. That is what binds the variant file to the
//     corpus: if the file were regenerated from a drifted shape, variant 0
//     would stop matching testdata/wire/bench_mixed.bin.
//   - the file is exactly 64 golden-sized records. Fixed width is §2.7's
//     structure-pinning rule made checkable: a driver derives its record
//     size as filesize/64, so a variant of any other length would silently
//     shift every later record.
//   - the 64 records are pairwise distinct. §2.7 rotates 64 buffers so that
//     one buffer cannot be memorised by the branch predictor and the caches;
//     a tool that emitted the pinned instance 64 times would pass every
//     other check here and quietly defeat that.
const (
	variantsPath  = "variants/bench_mixed.variants.bin"
	goldenPath    = "../../testdata/wire/bench_mixed.bin"
	numVariants   = 64  // BENCH-STANDARD §2.7's rotating-buffer count
	variantBytes  = 438 // BenchMixed's pinned wire (§1.3a); the golden is the authority
	variantsBytes = numVariants * variantBytes
)

func TestBenchMixedVariants(t *testing.T) {
	golden, err := os.ReadFile(goldenPath)
	if err != nil {
		t.Fatal(err)
	}
	data, err := os.ReadFile(variantsPath)
	if err != nil {
		t.Fatalf("%v — regenerate with `make bench-variants`", err)
	}

	if len(golden) != variantBytes {
		t.Errorf("golden bench_mixed.bin is %d bytes, §1.3a says %d — the golden wins, and this constant needs correcting",
			len(golden), variantBytes)
	}
	if len(data) != numVariants*len(golden) {
		t.Fatalf("variant file is %d bytes, want %d x %d = %d — every variant must be exactly as long as the golden (§2.7: structure fields pinned, bytes/op fixed)",
			len(data), numVariants, len(golden), numVariants*len(golden))
	}
	if len(data) != variantsBytes {
		t.Errorf("variant file is %d bytes, §1.3a's 438-byte shape says %d", len(data), variantsBytes)
	}

	if !bytes.Equal(data[:len(golden)], golden) {
		t.Errorf("variant 0 is not the golden — the variant data is not bound to testdata/wire/bench_mixed.bin; regenerate with `make bench-variants`")
	}

	seen := make(map[string]int, numVariants)
	for k := range numVariants {
		record := data[k*len(golden) : (k+1)*len(golden)]
		if prev, dup := seen[string(record)]; dup {
			t.Errorf("variant %d is byte-identical to variant %d — the 64 rotating buffers must differ (§2.7)", k, prev)
			continue
		}
		seen[string(record)] = k
	}
}
